            if (!isfinite(c->m[i][j])) {
                *orth = INFINITY;
                *det = 0.0;
                return ADCS_E_NOT_FINITE;
            }
        }
    }

    adcs_mat3_t ct = adcs_mat3_transpose(c);
    adcs_mat3_t cct = adcs_mat3_mul(c, &ct);

    adcs_mat3_t r = {{{0}}};
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            double val = cct.m[i][j];
            if (i == j) {
                val -= 1.0;
            }
            r.m[i][j] = val;
        }
    }

    double sum_sq = 0.0;
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            sum_sq += r.m[i][j] * r.m[i][j];
        }
    }
    *orth = sqrt(sum_sq);

    *det = adcs_mat3_det(c);

    return ADCS_OK;
}

